<?php
require 'config.php'; verify_csrf();
$page=$_GET['page']??(me()?'dashboard':'login');
if($_SERVER['REQUEST_METHOD']==='POST'){
 $action=$_POST['action']??'';
 if($action==='register'){
  $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pw=$_POST['password']??'';
  if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<10){$err='Enter a name, valid email and password of at least 10 characters.';}
  else{$level=(int)($_POST['level_id']??0);$group=(int)($_POST['group_id']??0);$s=$conn->prepare("INSERT INTO users(name,email,password_hash,role,student_no,campus,programme,level_id,group_id,status) VALUES(?,?,?,'student',?,?,?,?,?,'pending')");
   $hash=password_hash($pw,PASSWORD_DEFAULT);$no=trim($_POST['student_no']??'');$camp=trim($_POST['campus']??'');$prog=trim($_POST['programme']??'');$s->bind_param('ssssssii',$name,$email,$hash,$no,$camp,$prog,$level,$group);
   if($s->execute()){$success='Registration submitted. An administrator must approve your account.';}else{$err='Registration failed. The email may already be registered.';}
  }
 }
 if($action==='login'){$email=strtolower(trim($_POST['email']??''));$s=$conn->prepare("SELECT * FROM users WHERE email=? AND status='active'");$s->bind_param('s',$email);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){unset($u['password_hash']);$_SESSION['user']=$u;audit('login');redirect('dashboard');}else{$err='Invalid login or account not yet approved.';}}
 if($action==='logout'){session_destroy();redirect('login');}
 require_login();
 if($action==='approve_user'&&can(['admin'])){$id=(int)$_POST['id'];$s=$conn->prepare("UPDATE users SET status='active' WHERE id=?");$s->bind_param('i',$id);$s->execute();notify_user($id,'Account approved','Your BetterCom account is active.','index.php?page=dashboard');audit('approve user',(string)$id);redirect('users');}
 if($action==='create_user'&&can(['admin'])){$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$role=$_POST['role'];$pw=$_POST['password'];$hash=password_hash($pw,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(name,email,password_hash,role,status) VALUES(?,?,?,?, 'active')");$s->bind_param('ssss',$name,$email,$hash,$role);$s->execute();audit('create user',$email);redirect('users');}
 if($action==='create_level'&&can(['admin'])){$n=trim($_POST['name']);$s=$conn->prepare('INSERT INTO academic_levels(name) VALUES(?)');$s->bind_param('s',$n);$s->execute();redirect('academics');}
 if($action==='create_group'&&can(['admin'])){$n=trim($_POST['name']);$l=(int)$_POST['level_id'];$s=$conn->prepare('INSERT INTO student_groups(level_id,name) VALUES(?,?)');$s->bind_param('is',$l,$n);$s->execute();redirect('academics');}
 if($action==='create_module'&&can(['admin','hod','lecturer'])){$title=trim($_POST['title']);$code=trim($_POST['code']);$desc=trim($_POST['description']);$level=(int)$_POST['level_id'];$group=(int)($_POST['group_id']??0);$lect=(can(['lecturer'])?me()['id']:(int)$_POST['lecturer_id']);$s=$conn->prepare('INSERT INTO modules(code,title,description,level_id,group_id,lecturer_id) VALUES(?,?,?,?,NULLIF(?,0),?)');$s->bind_param('sssiii',$code,$title,$desc,$level,$group,$lect);$s->execute();audit('create module',$title);redirect('modules');}
 if($action==='announcement'&&can(['admin','it_admin','hod','lecturer','class_rep'])){$t=trim($_POST['title']);$b=trim($_POST['body']);$type=$_POST['audience_type'];$aid=(int)($_POST['audience_id']??0);$s=$conn->prepare('INSERT INTO announcements(title,body,audience_type,audience_id,author_id) VALUES(?,?,?,?,?)');$s->bind_param('sssii',$t,$b,$type,$aid,me()['id']);$s->execute();audit('publish announcement',$t);redirect('announcements');}
 if($action==='ticket' ){$cat=$_POST['category'];$subject=trim($_POST['subject']);$desc=trim($_POST['description']);$resp=$_POST['responsibility'];$prio=$_POST['priority'];$no='BC-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=$conn->prepare('INSERT INTO tickets(ticket_no,requester_id,category,subject,description,priority,responsibility) VALUES(?,?,?,?,?,?,?)');$s->bind_param('sisssss',$no,me()['id'],$cat,$subject,$desc,$prio,$resp);$s->execute();$id=$conn->insert_id;audit('create ticket',$no);redirect('tickets');}
 if($action==='ticket_update'&&can(['admin','it_admin','technician'])){$id=(int)$_POST['id'];$status=$_POST['status'];$assignee=(int)($_POST['assignee_id']??0);$note=trim($_POST['note']);$s=$conn->prepare('UPDATE tickets SET status=?,assignee_id=NULLIF(?,0) WHERE id=?');$s->bind_param('sii',$status,$assignee,$id);$s->execute();$u=$conn->prepare('INSERT INTO ticket_updates(ticket_id,user_id,note,status) VALUES(?,?,?,?)');$u->bind_param('iiss',$id,$_SESSION['user']['id'],$note,$status);$u->execute();$q=$conn->query("SELECT requester_id,ticket_no FROM tickets WHERE id=$id")->fetch_assoc();notify_user($q['requester_id'],'Ticket updated',$q['ticket_no'].' is now '.$status,'index.php?page=tickets');redirect('tickets');}
 if($action==='message'){$body=trim($_POST['body']);$to=(int)($_POST['recipient_id']??0);$group=(int)($_POST['group_id']??0);$module=(int)($_POST['module_id']??0);$s=$conn->prepare('INSERT INTO messages(sender_id,recipient_id,group_id,module_id,body) VALUES(?,NULLIF(?,0),NULLIF(?,0),NULLIF(?,0),?)');$s->bind_param('iiiis',$_SESSION['user']['id'],$to,$group,$module,$body);$s->execute();redirect('messages');}
 if($action==='meeting'&&can(['admin','it_admin','hod','lecturer'])){$title=trim($_POST['title']);$room='bc-'.bin2hex(random_bytes(8));$desc=trim($_POST['description']);$module=(int)($_POST['module_id']??0);$group=(int)($_POST['group_id']??0);$start=$_POST['starts_at']?:null;$end=$_POST['ends_at']?:null;$type=$_POST['meeting_type'];$s=$conn->prepare('INSERT INTO meetings(title,description,room_name,host_id,module_id,group_id,starts_at,ends_at,meeting_type) VALUES(?,?,?,?,NULLIF(?,0),NULLIF(?,0),?,?,?)');$s->bind_param('sssiiisss',$title,$desc,$room,$_SESSION['user']['id'],$module,$group,$start,$end,$type);$s->execute();audit('schedule meeting',$title);redirect('meetings');}
 if($action==='asset'&&can(['admin','it_admin','technician'])){$tag=trim($_POST['asset_tag']);$n=trim($_POST['name']);$cat=trim($_POST['category']);$camp=trim($_POST['campus']);$loc=trim($_POST['location']);$s=$conn->prepare('INSERT INTO assets(asset_tag,name,category,campus,location) VALUES(?,?,?,?,?)');$s->bind_param('sssss',$tag,$n,$cat,$camp,$loc);$s->execute();redirect('assets');}
}
function rows($sql){global $conn;return $conn->query($sql)->fetch_all(MYSQLI_ASSOC);}
function options($sql,$value,$label){foreach(rows($sql) as $r)echo '<option value="'.e($r[$value]).'">'.e($r[$label]).'</option>';}
function field($label,$name,$type='text',$required=true){echo '<label class="form-label">'.e($label).'</label><input class="form-control mb-3" name="'.e($name).'" type="'.e($type).'" '.($required?'required':'').'>';}
