<input type="hidden" name="id" value="<?=$t['id']?>"><div class="col-md-3"><select class="form-select" name="status"><?php foreach(['open','assigned','in_progress','referred','resolved','closed'] as $v)echo '<option '.($v===$t['status']?'selected':'').'>'.$v.'</option>';?></select></div><div class="col-md-3"><select class="form-select" name="assignee_id"><option value="0">Unassigned</option><?php options("SELECT id,name FROM users WHERE role='technician' OR role='it_admin'",'id','name');?></select></div><div class="col-md-4"><input class="form-control" name="note" placeholder="Update / resolution note" required></div><div class="col-md-2"><button class="btn btn-outline-primary">Update</button></div></form><?php endif;?></div><?php endforeach;?></div>
